package com.geekathon.guardpet
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.view.*;import android.widget.*
class LetterActivity:Activity(){ lateinit var box:LinearLayout; override fun onCreate(b:Bundle?){super.onCreate(b);box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(32,40,32,32);setBackgroundColor(Color.rgb(238,248,250))}; title="Miku 回信箱"; render();setContentView(box)}
fun render(){box.removeAllViews(); val h=TextView(this).apply{text="Miku 的回信箱";textSize=28f;setTextColor(Color.rgb(35,52,91));setPadding(0,0,0,24)};box.addView(h);val input=EditText(this).apply{hint="今天想告诉 Miku 什么呢？";minLines=8;gravity=android.view.Gravity.TOP;setBackgroundColor(Color.WHITE);setPadding(20,20,20,20)};box.addView(input,LinearLayout.LayoutParams(-1,0,1f));val send=Button(this).apply{text="寄给 Miku"};box.addView(send);send.setOnClickListener{if(input.text.isNullOrBlank())return@setOnClickListener;send.isEnabled=false;Toast.makeText(this,"Miku 正在读这封信……",Toast.LENGTH_SHORT).show();Handler(mainLooper).postDelayed({showReply(input.text.toString())},1400)}}
fun showReply(t:String){box.removeAllViews();val e=TextView(this).apply{text="✉  来自 Miku\n\n亲爱的你：\n\n谢谢你把今天写给我。无论发生了什么，我都会安静地听你说。慢慢来，你已经做得很好了。\n\n—— Miku\n\n✦ 我把这件事记在心里了";textSize=20f;setTextColor(Color.rgb(35,52,91));setLineSpacing(10f,1.15f);setPadding(28,36,28,36);setBackgroundColor(Color.rgb(255,253,248))};box.addView(e,LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="返回信箱"};box.addView(back);back.setOnClickListener{render()}}
}
